{"stdout":"<?php\n\nnamespace App\\Models;\n\nuse Database\\Factories\\FinancialReportFactory;\nuse Illuminate\\Database\\Eloquent\\Attributes\\Fillable;\nuse Illuminate\\Database\\Eloquent\\Factories\\HasFactory;\nuse Illuminate\\Database\\Eloquent\\Model;\nuse Illuminate\\Database\\Eloquent\\Relations\\BelongsTo;\n\n#[Fillable([\n    'enterprise_id',\n    'financial_period_id',\n    'financial_account_id',\n    'transaction_category_id',\n    'currency',\n    'metrics',\n    'source_snapshot',\n    'generated_at',\n])]\nclass FinancialReport extends Model\n{\n    /** @use HasFactory<FinancialReportFactory> */\n    use HasFactory;\n\n    /** @return BelongsTo<Enterprise, $this> */\n    public function enterprise(): BelongsTo\n    {\n        return $this->belongsTo(Enterprise::class);\n    }\n\n    /** @return BelongsTo<FinancialPeriod, $this> */\n    public function financialPeriod(): BelongsTo\n    {\n        return $this->belongsTo(FinancialPeriod::class);\n    }\n\n    /** @return BelongsTo<FinancialAccount, $this> */\n    public function financialAccount(): BelongsTo\n    {\n        return $this->belongsTo(FinancialAccount::class);\n    }\n\n    /** @return BelongsTo<TransactionCategory, $this> */\n    public function category(): BelongsTo\n    {\n        return $this->belongsTo(TransactionCategory::class, 'transaction_category_id');\n    }\n\n    /** @return array<string, string> */\n    protected function casts(): array\n    {\n        return [\n            'metrics' => 'array',\n            'source_snapshot' => 'array',\n            'generated_at' => 'datetime',\n        ];\n    }\n}\n","stderr":"","exitCode":0,"timedOut":false,"truncated":false}